namespace BlazorApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 4;

    private readonly List<Notification> _notifications =
    [
        new(1, "Welcome to the app!", DateTime.Now.AddMinutes(-10)),
        new(2, "Your profile was updated.", DateTime.Now.AddMinutes(-5)),
        new(3, "New feature: dark mode is available.", DateTime.Now.AddMinutes(-1)),
    ];

    public Task<List<Notification>> GetNotificationsAsync()
    {
        return Task.FromResult(_notifications.ToList());
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(DateTime since)
    {
        // Simulate new notifications arriving occasionally
        if (Random.Shared.Next(3) == 0)
        {
            _notifications.Add(new(_nextId++, $"New alert at {DateTime.Now:T}", DateTime.Now));
        }

        var newer = _notifications.Where(n => n.Timestamp > since).ToList();
        return Task.FromResult(newer);
    }
}

@page "/notifications"
@rendermode InteractiveServer
@inject BlazorApp.Services.NotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@notifications.Count</span></h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item">
                <strong>@n.Message</strong>
                <small class="text-muted ms-2">@n.Timestamp.ToString("g")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<BlazorApp.Services.Notification>? PersistedNotifications { get; set; }

    private List<BlazorApp.Services.Notification> notifications = new();
    private CancellationTokenSource? _cts;
    private DateTime _lastCheck;

    protected override async Task OnInitializedAsync()
    {
        // Only fetch if state wasn't restored from prerender
        PersistedNotifications ??= await NotificationService.GetNotificationsAsync();
        notifications = PersistedNotifications;
        _lastCheck = notifications.Count > 0
            ? notifications.Max(n => n.Timestamp)
            : DateTime.Now;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Start polling only after the component is interactive
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(5000, ct).ConfigureAwait(false);

            var newer = await NotificationService.GetNotificationsSinceAsync(_lastCheck);
            if (newer.Count > 0)
            {
                _lastCheck = newer.Max(n => n.Timestamp);
                notifications.AddRange(newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

