@code {
    private const string PersistenceKey = "notifications";
    private List<BlazorApp.Services.Notification> notifications = new();
    private CancellationTokenSource? _cts;
    private DateTime _lastCheck;
    private PersistingComponentStateSubscription _persistingSubscription;

    protected override async Task OnInitializedAsync()
    {
        _persistingSubscription = ApplicationState.RegisterOnPersisting(PersistState);

        if (!ApplicationState.TryTakeFromJson<List<BlazorApp.Services.Notification>>(PersistenceKey, out var restored))
        {
            notifications = await NotificationService.GetNotificationsAsync();
        }
        else
        {
            notifications = restored!;
        }

        _lastCheck = notifications.Count > 0
            ? notifications.Max(n => n.Timestamp)
            : DateTime.Now;
    }

    private Task PersistState()
    {
        ApplicationState.PersistAsJson(PersistenceKey, notifications);
        return Task.CompletedTask;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Start polling only after the component is interactive
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(5000, ct);
            }
            catch (TaskCanceledException)
            {
                break;
            }

            var newer = await NotificationService.GetNotificationsSinceAsync(_lastCheck);
            if (newer.Count > 0)
            {
                _lastCheck = newer.Max(n => n.Timestamp);
                notifications.AddRange(newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        _persistingSubscription.Dispose();
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

